def transform(grid):
    h, w = len(grid), len(grid[0])

    # The distinctive color marks a stencil; all other cells are background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    color = max((v for v in counts if v not in (0,)), key=lambda v: counts[v])
    # The stencil color is the nonzero color that is not the dominant background.
    color = min((v for v in counts if v != 0), key=lambda v: counts[v])

    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, c in points)
    min_c = min(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for top in range(h - sh + 1):
        for left in range(w - sw + 1):
            if all(grid[top + dr][left + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[top + dr][left + dc] = color
    return out
